    #[test]
    fn ordinary_uncertainty_adaptation_keeps_its_shape_and_root_bounds() {
        let work = sequence_work();
        let state = read_state(&work, &["entry-ref", "flow-ref"]);
        let proposal_value = || {
            let mut value =
                serde_json::to_value(proposal_input("entry-ref", "note", "entry-ref", "flow-ref"))
                    .unwrap();
            value.as_object_mut().unwrap().remove("uncertainties");
            value["operations"][0]["uncertainties"] = json!(["  bounded value  "]);
            value
        };

        let original = proposal_value();
        let (adapted, _) = adapt_ordinary_sequence_uncertainties(&work, &state, &original).unwrap();
        assert_eq!(adapted["uncertainties"], json!(["  bounded value  "]));
        assert!(adapted["operations"][0].get("uncertainties").is_none());
        let mut expected = original.clone();
        let uncertainties = expected["operations"][0]
            .as_object_mut()
            .unwrap()
            .remove("uncertainties")
            .unwrap();
        expected
            .as_object_mut()
            .unwrap()
            .insert("uncertainties".into(), uncertainties);
        assert_eq!(adapted, expected);

        let mut empty = proposal_value();
        empty["operations"][0]["uncertainties"] = json!([]);
        let (adapted_empty, _) =
            adapt_ordinary_sequence_uncertainties(&work, &state, &empty).unwrap();
        assert_eq!(adapted_empty["uncertainties"], json!([]));

        for root_uncertainties in [Value::Null, json!([]), json!(["already at root"])] {
            let mut existing_root = proposal_value();
            existing_root["uncertainties"] = root_uncertainties;
            assert!(adapt_ordinary_sequence_uncertainties(&work, &state, &existing_root).is_none());
        }

        let mut multiple_operations = proposal_value();
        let second = multiple_operations["operations"][0].clone();
        multiple_operations["operations"]
            .as_array_mut()
            .unwrap()
            .push(second);
        assert!(
            adapt_ordinary_sequence_uncertainties(&work, &state, &multiple_operations).is_none()
        );

        for malformed in [
            json!([""]),
            json!(["  \n  "]),
            json!("not-an-array"),
            json!([1]),
            json!(["x".repeat(2049)]),
            json!(vec!["bounded"; 65]),
        ] {
            let mut invalid = proposal_value();
            invalid["operations"][0]["uncertainties"] = malformed;
            assert!(adapt_ordinary_sequence_uncertainties(&work, &state, &invalid).is_none());
        }

        let mut unknown = proposal_value();
        unknown["operations"][0]["verification"] = json!("APPROVED");
        assert!(adapt_ordinary_sequence_uncertainties(&work, &state, &unknown).is_none());

        let mut section_work = sequence_work();
        section_work.request.entrypoint = Some("section-entities".into());
        section_work.handles.insert(
            "section-ref".into(),
            super::super::work::Handle {
                kind: "SECTION".into(),
                id: "section-entities".into(),
            },
        );
        let section_state = read_state(&section_work, &["entry-ref"]);
        let section = json!({
            "schema":"codeclew-documentation-proposal/1.0",
            "operations":[{
                "entrypoint":"section-ref",
                "title":"Entities",
                "summary":{"text":"Describes domain entities.","evidence":["entry-ref"]},
                "steps":[],
                "uncertainties":["bounded value"]
            }]
        });
        assert!(
            adapt_ordinary_sequence_uncertainties(&section_work, &section_state, &section)
                .is_none()
        );
    }

    fn collect_source_parts(
        repo: &Repository,
        work: &super::super::work::Work,
    ) -> (Vec<Value>, super::super::work::ReadState) {
        let mut cursor = None;
        let mut parts = Vec::new();
        loop {
            let part = super::super::work_parts::read_part_loaded(
                repo,
                work,
                super::super::work_parts::SourcePartRequest {
                    schema: super::super::work_parts::REQUEST_SCHEMA.into(),
                    reference: "source-ref".into(),
                    cursor: cursor.clone(),
                },
            )
            .unwrap();
            cursor = part["nextCursor"].as_str().map(str::to_owned);
            parts.push(part);
            if cursor.is_none() {
                break;
            }
        }
        let state = super::super::work::read_state(repo, &work.id).unwrap();
        (parts, state)
    }

    fn assert_author_evidence_schema(payload: &Value, expected: Value) {
        for path in [
            "/outputSchema/$defs/claim/properties/evidence/items",
            "/outputSchema/$defs/visualClaim/properties/evidence/items",
            "/outputSchema/$defs/assertion/properties/evidence",
        ] {
            assert_eq!(payload.pointer(path), Some(&expected), "{path}");
        }
    }

    fn assert_shared_selection_schema(output_schema: &Value) {
        let shared = super::super::section_author::output_schema().unwrap();
        assert_eq!(
            output_schema["$defs"]["selection"],
            shared["$defs"]["selection"]
        );
    }

    fn assert_local_schema_references(root: &Value, node: &Value) {
        match node {
            Value::Object(properties) => {
                if let Some(reference) = properties.get("$ref").and_then(Value::as_str) {
                    assert!(
                        reference.starts_with('#'),
                        "unexpected external schema reference"
                    );
                    assert!(
                        root.pointer(&reference[1..]).is_some(),
                        "unresolved reference {reference}"
                    );
                }
                for value in properties.values() {
                    assert_local_schema_references(root, value);
                }
            }
            Value::Array(values) => {
                for value in values {
                    assert_local_schema_references(root, value);
                }
            }
            _ => {}
        }
    }

    #[test]
    fn locked_checkpoint_selection_uses_held_guard_and_reloads_after_release() {
        let temporary = tempfile::tempdir().unwrap();
        super::super::store::Repository::init(temporary.path(), "Locked checkpoint").unwrap();
        let repo = Repository::open(temporary.path()).unwrap();
        let work = "a".repeat(64);
        let run = "b".repeat(32);
        let config_digest = digest(&json!({"config":"fixture"})).unwrap();
        let driver_digests = BTreeMap::from([
            ("author".into(), digest(&json!("author-driver")).unwrap()),
            (
                "reviewer".into(),
                digest(&json!("reviewer-driver")).unwrap(),
            ),
        ]);
        let mut report = RunReport {
            schema: "codeclew-documentation-work-run/1.0".into(),
            run: run.clone(),
            work: work.clone(),
            status: "PREPARED".into(),
            config_digest: Some(config_digest.clone()),
            attempts: Vec::new(),
            proposal: None,
            review: None,
            publication: None,
            gap: None,
            accounting: None,
            context_budget: None,
            execution_mode: None,
            draft: None,
            draft_repair: None,
            draft_review: None,
            draft_review_retry: None,
            checkpoint: None,
        };
        let checkpoint = RunCheckpoint::new(
            &report,
            format!("sha256:{}/1", "0".repeat(64)),
            config_digest.clone(),
            driver_digests.clone(),
            digest(&json!({"reads":[]})).unwrap(),
        );
        let guard = repo.lock().unwrap();
        save_run_checkpoint_locked(&repo, &guard, &mut report, &checkpoint).unwrap();
        let selected_reference = report.checkpoint.clone().unwrap();
        drop(guard);

        let selected_report = latest_report(&repo, &work).unwrap().unwrap();
        assert_eq!(selected_report.checkpoint, Some(selected_reference));
        let loaded = load_run_checkpoint(&repo, &selected_report, &config_digest, &driver_digests)
            .unwrap()
            .expect("selected immutable checkpoint reloads after guard release");
        assert_eq!(loaded.run, run);
        assert_eq!(loaded.work, work);
        assert_eq!(loaded.phase, "AUTHOR");
    }

