        let mut work = endpoint_context_fixture();
        let names: Vec<_> = (0..9).map(|index| format!("injected{index:02}")).collect();
        let references = names
            .iter()
            .map(|name| format!("      this.{name} = null;\n"))
            .collect::<String>();
