        )
        .unwrap();
        assert!(
            context
                .iter()
                .any(|item| { item["kind"] == "DEPENDENCY" && item["id"] == "call-main" })
        );
        assert!(
            context
                .iter()
                .any(|item| { item["kind"] == "DEPENDENCY" && item["id"] == "helper-main" })
        );
        assert!(
            context
                .iter()
                .any(|item| { item["kind"] == "DEPENDENCY" && item["id"] == "helper-main-flow" })
        );
